const R = bend_radius;
for (let pr = 0; pr < nprims(0); pr++) {
  const ids = primpoints(0, pr); if (ids.length < 2) continue;
  const P = ids.map((i) => point(0, 'P', i)), out = [P[0]];
  for (let i = 1; i < P.length - 1; i++) {
    const u = sub(P[i - 1], P[i]), v = sub(P[i + 1], P[i]), lu = length(u), lv = length(v);
    if (R <= 0 || lu < 1e-9 || lv < 1e-9) { out.push(P[i]); continue; }
    const a = normalize(u), b = normalize(v), th = Math.acos(clamp(dot(a, b), -1, 1));
    if (th > PI - 1e-3 || th < 1e-3) { out.push(P[i]); continue; }
    let d = R / Math.tan(th / 2); d = Math.min(d, lu / 2, lv / 2); const r = d * Math.tan(th / 2);
    const t1 = add(P[i], mul(a, d)), t2 = add(P[i], mul(b, d)), c = add(P[i], mul(normalize(add(a, b)), r / Math.sin(th / 2)));
    const e1 = sub(t1, c), e2 = sub(t2, c), phi = PI - th, n = Math.max(2, Math.ceil(phi / radians(10)));
    for (let k = 0; k <= n; k++) { const s = k / n; out.push(add(c, mul(add(mul(e1, Math.sin((1 - s) * phi)), mul(e2, Math.sin(s * phi))), 1 / Math.sin(phi)))); }
  }
  out.push(P[P.length - 1]);
  addprim(0, 'polyline', out.map((p) => addpoint(0, p)));
  removeprim(0, pr, true);
}
